#include <vector>
#define main hecbench_original_main
#include "graphExecution-cuda/main.cu"
#undef main
void emit(int trial,double seconds,const std::vector<double>&result,const std::vector<double>&expected,int repeat,double atol=0.,double rtol=0.){
 double error=0;bool correct=result.size()==expected.size();for(size_t i=0;i<result.size();i++){double e=fabs(result[i]-expected[i]);error=fmax(error,e);correct &= std::isfinite(result[i])&&e<=atol+rtol*fabs(expected[i]);}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(result.data(),8,result.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"timing_region\":\"graph_and_stream_segment_total_including_h2d_d2h\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,correct?"true":"false",result.size(),error,repeat,path,result.size());if(!correct)exit(1);
}
int main(int argc,char**argv){int n=argc>1?atoi(argv[1]):262144,inner=argc>2?atoi(argv[2]):100,nblocks=512;float*input;double*result_h;cudaMallocHost(&input,n*4);cudaMallocHost(&result_h,8);std::vector<double>expectedone(nblocks+1,0.);for(int i=0;i<n;i++){input[i]=float((i*17+3)%256)/float(2147483647);expectedone[(i%(nblocks*256))/256]+=double(input[i]);expectedone[nblocks]+=double(input[i]);}std::vector<double>expected=expectedone;expected.insert(expected.end(),expectedone.begin(),expectedone.end());float*di;double*partial,*result;cudaMalloc(&di,n*4);cudaMalloc(&partial,nblocks*8);cudaMalloc(&result,8);cudaStream_t stream;cudaStreamCreate(&stream);auto segment=[&](){cudaMemcpyAsync(di,input,n*4,cudaMemcpyHostToDevice,stream);for(int j=0;j<inner;j++){cudaMemsetAsync(partial,0,nblocks*8,stream);reduce<<<nblocks,256,0,stream>>>(di,partial,n,nblocks);reduceFinal<<<1,256,0,stream>>>(partial,result,nblocks);}cudaMemcpyAsync(result_h,result,8,cudaMemcpyDeviceToHost,stream);};segment();cudaStreamSynchronize(stream);cudaGraph_t graph;cudaGraphExec_t executable;cudaStreamBeginCapture(stream,cudaStreamCaptureModeGlobal);segment();cudaStreamEndCapture(stream,&graph);cudaGraphInstantiate(&executable,graph,nullptr,nullptr,0);cudaGraphLaunch(executable,stream);cudaStreamSynchronize(stream);for(int trial=1;trial<=5;trial++){double total=0;std::vector<double>values;for(int mode=1;mode<=2;mode++){auto start=std::chrono::steady_clock::now();if(mode==1)cudaGraphLaunch(executable,stream);else segment();cudaStreamSynchronize(stream);total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::vector<double>v(nblocks);cudaMemcpy(v.data(),partial,nblocks*8,cudaMemcpyDeviceToHost);values.insert(values.end(),v.begin(),v.end());values.push_back(result_h[0]);}emit(trial,total,values,expected,inner,1e-6);}cudaGraphExecDestroy(executable);cudaGraphDestroy(graph);cudaStreamDestroy(stream);cudaFree(di);cudaFree(partial);cudaFree(result);cudaFreeHost(input);cudaFreeHost(result_h);return 0;}
